<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> -</span><span style="color:#ABB2BF;"> x) </span><span style="color:#56B6C2;">**</span><span style="color:#ABB2BF;"> gamma </span><span style="color:#56B6C2;">*</span><span style="color:#ABB2BF;"> np.</span><span style="color:#61AFEF;">log</span><span style="color:#ABB2BF;">(x)</span></span>
